String deriveName(String baseUrl) {
  final uri = Uri.tryParse(baseUrl);
  var host = uri?.host ?? baseUrl;
  if (host.isEmpty) host = 'custom';
  final port = uri?.port;
  final defaultPort = uri?.scheme == 'https' ? 443 : 80;
  final candidate = port != null && port != defaultPort
